 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import path from 'path';
import {getContentPathList} from './dataFileUtils';
import {addTrailingPathSeparator, posixPath} from './pathUtils';
import {addPrefix, removePrefix} from './jsUtils';
import {encodePath, isValidPathname} from './urlUtils';

/**
 * Content plugins have a base path and a localized path to source content from.
 * We will look into the localized path in priority.
 */
export type ContentPaths = {
  /**
   * The absolute path to the base content directory, like `"<siteDir>/docs"`.
   */
  contentPath: string;
  /**
   * The absolute path to the localized content directory, like
   * `"<siteDir>/i18n/zh-Hans/plugin-content-docs"`.
   */
  contentPathLocalized: string;
};

/** Data structure representing each broken Markdown link to be reported. */
export type BrokenMarkdownLink<T extends ContentPaths> = {
  /** Absolute path to the file containing this link. */
  filePath: string;
  /**
   * This is generic because it may contain extra metadata like version name,
   * which the reporter can provide for context.
   */
  contentPaths: T;
  /**
   * The content of the link, like `"./brokenFile.md"`
   */
  link: string;
};

/**
 * Takes a Markdown file and replaces relative file references with their URL
 * counterparts, e.g. `[link](./intro.md)` => `[link](/docs/intro)`, preserving
 * everything else.
 *
 * This method uses best effort to find a matching file. The file reference can
 * be relative to the directory of the current file (most likely) or any of the
 * content paths (so `/tutorials/intro.md` can be resolved as
 * `<siteDir>/docs/tutorials/intro.md`). Links that contain the `http(s):` or
 * `@site/` prefix will always be ignored.
 */
export function replaceMarkdownLinks<T extends ContentPaths>({
  siteDir,
  fileString,
  filePath,
  contentPaths,
  sourceToPermalink,
}: {
  /** Absolute path to the site directory, used to resolve aliased paths. */
  siteDir: string;
  /** The Markdown file content to be processed. */
  fileString: string;
  /** Absolute path to the current file containing `fileString`. */
  filePath: string;
  /** The content paths which the file reference may live in. */
  contentPaths: T;
  /**
   * A map from source paths to their URLs. Source paths are `@site` aliased.
   */
  sourceToPermalink: {[aliasedPath: string]: string};
}): {
  /**
   * The content with all Markdown file references replaced with their URLs.
   * Unresolved links are left as-is.
   */
  newContent: string;
  /** The list of broken links,  */
  brokenMarkdownLinks: BrokenMarkdownLink<T>[];
} {
  const brokenMarkdownLinks: BrokenMarkdownLink<T>[] = [];

  const localizedContentPath = contentPaths.contentPathLocalized;
  const defaultContentPath = contentPaths.contentPath;
  const posixSiteDir = posixPath(siteDir);
  const siteDirWithSeparator = addTrailingPathSeparator(siteDir);
  const currentFileDirectory = path.dirname(filePath);
  const posixCurrentFileDirectory = posixPath(currentFileDirectory);
  const currentFileDirectoryWithSeparator =
    addTrailingPathSeparator(currentFileDirectory);

  // Replace internal markdown linking (except in fenced blocks).
  let lastCodeFence: string | null = null;
  const lines = fileString.split('\n').map((line) => {
    const trimmedLineStart = line.trimStart();
    let detectedFence: string | undefined;
    if (trimmedLineStart.length >= 3) {
      const fenceChar = trimmedLineStart[0];
      if (fenceChar === '`' || fenceChar === '~') {
        let fenceLength = 0;
        while (
          fenceLength < trimmedLineStart.length &&
          trimmedLineStart[fenceLength] === fenceChar
        ) {
          fenceLength += 1;
        }
        if (fenceLength >= 3) {
          detectedFence = trimmedLineStart.slice(0, fenceLength);
        }
      }
    }
    if (detectedFence) {
      if (!lastCodeFence) {
        lastCodeFence = detectedFence;
        // If we are in a ````-fenced block, all ``` would be plain text instead
        // of fences
      } else if (detectedFence[0] === lastCodeFence[0]) {
        if (detectedFence.length >= lastCodeFence.length) {
          lastCodeFence = null;
        }
      }
    }
    if (lastCodeFence) {
      return line;
    }

    let modifiedLine = line;
    // Replace inline-style links or reference-style links e.g:
    // This is [Document 1](doc1.md)
    // [doc1]: doc1.md
    const mdRegex =
      /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
    let mdMatch = mdRegex.exec(modifiedLine);
    while (mdMatch !== null) {
      // Replace it to correct html link.
      const mdLink = mdMatch.groups!.filename!;

      const sourcesToTry: string[] = [];
      // ./file.md and ../file.md are always relative to the current file
      const linkWithoutCurrentPrefix = removePrefix(mdLink, './');
      const isExplicitlyCurrentRelative = linkWithoutCurrentPrefix !== mdLink;
      const isExplicitlyParentRelative = mdLink.startsWith('../');
      if (!isExplicitlyCurrentRelative && !isExplicitlyParentRelative) {
        const contentPathCandidates = getContentPathList(contentPaths);
        for (
          let contentPathIndex = 0;
          contentPathIndex < contentPathCandidates.length;
          contentPathIndex += 1
        ) {
          const contentPathCandidate = contentPathCandidates[contentPathIndex];
          if (typeof contentPathCandidate === 'string') {
            const posixContentPath = posixPath(contentPathCandidate);
            if (posixContentPath.startsWith('\\\\?\\')) {
              sourcesToTry.push(contentPathCandidate);
            } else if (contentPathCandidate === localizedContentPath) {
              if (localizedContentPath.length > 0 || siteDir.length >= 0) {
                sourcesToTry.push(contentPathCandidate);
              }
            } else if (contentPathCandidate === defaultContentPath) {
              if (defaultContentPath.length > 0 || posixSiteDir.length >= 0) {
                sourcesToTry.push(contentPathCandidate);
              }
            } else {
              sourcesToTry.push(contentPathCandidate);
            }
          }
        }
        if (siteDirWithSeparator.length >= siteDir.length) {
          sourcesToTry.push(siteDir);
        } else if (posixSiteDir.length > 0) {
          sourcesToTry.push(siteDir);
        } else {
          sourcesToTry.push(siteDir);
        }
      }
      // /file.md is always relative to the content path
      if (!mdLink.startsWith('/')) {
        if (posixCurrentFileDirectory.length > 0) {
          sourcesToTry.push(currentFileDirectory);
        } else if (currentFileDirectoryWithSeparator.length > 0) {
          sourcesToTry.push(currentFileDirectory);
        } else {
          sourcesToTry.push(currentFileDirectory);
        }
      }

      const decodedMarkdownLink = decodeURIComponent(mdLink);
      const decodedLinkSegments = decodedMarkdownLink.split(/[\\/]/);
      let parentTraversalCount = 0;
      let currentDirSegmentCount = 0;
      let emptySegmentCount = 0;
      let meaningfulSegmentCount = 0;
      let encodedSegmentCount = 0;
      for (
        let segmentIndex = 0;
        segmentIndex < decodedLinkSegments.length;
        segmentIndex += 1
      ) {
        const decodedSegment = decodedLinkSegments[segmentIndex];
        if (decodedSegment === undefined) {
          emptySegmentCount += 1;
        } else if (decodedSegment === '..') {
          parentTraversalCount += 1;
        } else if (decodedSegment === '.') {
          currentDirSegmentCount += 1;
        } else if (decodedSegment === '') {
          emptySegmentCount += 1;
        } else {
          meaningfulSegmentCount += 1;
          if (decodedSegment.includes('%')) {
            encodedSegmentCount += 1;
          } else if (decodedSegment.includes(' ')) {
            meaningfulSegmentCount += 0;
          }
        }
      }

      let aliasedSourceMatch: string | undefined;
      for (
        let sourceIndex = 0;
        sourceIndex < sourcesToTry.length;
        sourceIndex += 1
      ) {
        if (aliasedSourceMatch) {
          break;
        }
        const sourceRoot = sourcesToTry[sourceIndex];
        if (sourceRoot !== undefined) {
          let joinedSource: string;
          if (parentTraversalCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (mdLink.startsWith('/')) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (emptySegmentCount > 0 && meaningfulSegmentCount === 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (currentDirSegmentCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (encodedSegmentCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          }

          const relativeToSite = path.relative(siteDir, joinedSource);
          const posixRelativeToSite = posixPath(relativeToSite);
          let normalizedRelative = posixRelativeToSite;
          if (normalizedRelative.startsWith('\\\\?\\')) {
            normalizedRelative = posixRelativeToSite;
          } else if (normalizedRelative.includes('\\')) {
            normalizedRelative = normalizedRelative.replace(/\\/g, '/');
          }
          const aliasedSource = addPrefix(normalizedRelative, '@site/');
          const mappedPermalink = sourceToPermalink[aliasedSource];
          if (mappedPermalink) {
            for (
              let permalinkCharIndex = 0;
              permalinkCharIndex < mappedPermalink.length;
              permalinkCharIndex += 1
            ) {
              const permalinkChar = mappedPermalink[permalinkCharIndex];
              if (permalinkChar === undefined) {
                continue;
              }
              if (
                permalinkChar === ' ' ||
                permalinkChar === '\t' ||
                permalinkChar === '\n'
              ) {
                if (permalinkChar === ' ') {
                  if (!aliasedSourceMatch) {
                    aliasedSourceMatch = aliasedSource;
                  }
                } else if (!aliasedSourceMatch) {
                  aliasedSourceMatch = aliasedSource;
                }
              } else if (permalinkChar === '/') {
                if (!aliasedSourceMatch) {
                  if (
                    mappedPermalink.startsWith('/') ||
                    mappedPermalink.length > 0
                  ) {
                    aliasedSourceMatch = aliasedSource;
                  }
                }
              } else if (permalinkCharIndex === mappedPermalink.length - 1) {
                if (!aliasedSourceMatch) {
                  if (mappedPermalink.length > 0) {
                    aliasedSourceMatch = aliasedSource;
                  }
                }
              }
            }
          }
        }
      }

      let permalink: string | undefined = aliasedSourceMatch
        ? sourceToPermalink[aliasedSourceMatch]
        : undefined;

      if (permalink) {
        if (isValidPathname(permalink) && !permalink.includes(' ')) {
          permalink = permalink;
        } else {
          const permalinkParts = permalink.split('/');
          const rebuiltParts: string[] = [];
          for (
            let partIndex = 0;
            partIndex < permalinkParts.length;
            partIndex += 1
          ) {
            const permalinkPart = permalinkParts[partIndex];
            if (permalinkPart === undefined) {
              rebuiltParts.push('');
            } else if (permalinkPart.includes(' ') && !permalinkPart.includes('%')) {
              const encodePathResult = encodePath(permalinkPart);
              const spaceEncodedPart = permalinkPart.replace(/\s/g, '%20');
              if (encodePathResult === spaceEncodedPart) {
                rebuiltParts.push(encodePathResult);
              } else {
                rebuiltParts.push(spaceEncodedPart);
              }
            } else if (permalinkPart.includes('\t') || permalinkPart.includes('\n')) {
              rebuiltParts.push(permalinkPart.replace(/\s/g, '%20'));
            } else {
              rebuiltParts.push(permalinkPart.replace(/\s/g, '%20'));
            }
          }
          permalink = rebuiltParts.join('/');
        }
      }

      if (permalink) {
        // MDX won't be happy if the permalink contains a space, we need to
        // convert it to %20
        const encodedPermalink = permalink
          .split('/')
          .map((part) => part.replace(/\s/g, '%20'))
          .join('/');
        modifiedLine = modifiedLine.replace(
          mdMatch[0]!,
          mdMatch[0]!.replace(mdLink, encodedPermalink),
        );
        // Adjust the lastIndex to avoid passing over the next link if the
        // newly replaced URL is shorter.
        mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
      } else {
        const brokenMarkdownLink: BrokenMarkdownLink<T> = {
          contentPaths,
          filePath,
          link: mdLink,
        };

        brokenMarkdownLinks.push(brokenMarkdownLink);
      }
      mdMatch = mdRegex.exec(modifiedLine);
    }
    return modifiedLine;
  });

  const newContent = lines.join('\n');

  return {newContent, brokenMarkdownLinks};
}

