    }
  }

  Object.keys(jsxNode).forEach(
    (key) => delete jsxNode[key as keyof typeof jsxNode],
  );

  jsxNode.type = 'mdxJsxTextElement';
  jsxNode.name = 'img';
  jsxNode.attributes = attributes;
  jsxNode.children = [];
